related_posts_container.javascript_exemplo:
const label = document.querySelector('.post-labels a')?.textContent;
if (label) {
  fetch(`/feeds/posts/default/-/${encodeURIComponent(label)}?alt=json&max-results=3`)
    .then(r => r.json())
    .then(data => {
      const container = document.getElementById('related-posts-container');
      data.feed.entry?.forEach(entry => {
        const title = entry.title.$t;
        const url = entry.link.find(l => l.rel === 'alternate').href;
        container.innerHTML += `<a href="${url}" class="d-block text-decoration-none mb-2 small fw-bold">${title}</a>`;
      });
    });
}
